	public static MobToteTable FindOrCreate(MobToteID _toteId, InventDim _inventDim = null, boolean _selectForUpdate = false)
    {
        MobToteTable		toteTable;
        MobPackingStation	packStation;
        //WHSContainerType	cont;

        toteTable.selectForUpdate(_selectForUpdate);

        select firstonly toteTable where toteTable.ToteId == _toteId;

		if (!toteTable)
        {
            toteTable.ToteId = _toteId;
            toteTable.PackingType = new MobDocPickOrder().parmDefaultContainerType();
			if (_inventDim)
            {
                packStation = MobPackingStation::FindByLocation(_inventDim.InventLocationId, _inventDim.wMSLocationId);
                toteTable.PackingType = packStation.DefaultContainerType ? packStation.DefaultContainerType : toteTable.PackingType;
            }
            toteTable.Weight = WHSContainerType::find(toteTable.PackingType).TareWeight;
            toteTable.Status = TFMDocumentQueueStatus::ReadyForProcessing;
            toteTable.insert();
        }
        return toteTable;
    }

public static MobToteTable Find(MobToteID _toteId,boolean _selectForUpdate = false)
{
    MobToteTable		toteTable;
    //MobPackingStation	packStation;
    //WHSContainerType	cont;

    toteTable.selectForUpdate(_selectForUpdate);

    select firstonly toteTable where toteTable.ToteId == _toteId;

    return toteTable;
}

public static MobToteTable Exists(MobToteID _toteId)
{
    MobToteTable		toteTable;


    select firstonly toteTable where toteTable.ToteId == _toteId;


    return toteTable;
}

    public boolean validateWrite()
    {
        boolean ret;
        WHSContainerTypeCode codeFrom, codeTo;

        ret = super();
        if (this.PackingType != this.orig().PackingType)
        {
            codeFrom = this.orig().PackingType;
            codeTo = this.PackingType;
            this.Weight += (WHSContainerType::find(codeTo).TareWeight - WHSContainerType::find(codeFrom).TareWeight);
		}		

        return ret;
    }

	public display WMSShipmentId shipments()
    {
        WMSShipmentId	shipmentId;
        MobToteContent	toteContent;
        WMSOrderTrans	wmsOrderTrans;
        Set				shipmentIds = new Set(Types::String);


		while select RefRecId from toteContent where toteContent.ToteId == this.ToteId && toteContent.Qty != 0
			join firstonly ShipmentId from wmsOrderTrans where wmsOrderTrans.RecId == toteContent.RefRecId
        {
            shipmentIds.add(wmsOrderTrans.shipmentId);
            shipmentId = wmsOrderTrans.shipmentId;
		}
		if ( shipmentIds.elements() > 1)
        {
            return "@SYS21762";
        }
        return shipmentId;
	}

public display WMSPickingRouteID pickingRoutes()
{
    WMSPickingRouteID	consolRoute;
    MobToteContent		toteContent;
    WMSOrderTrans		wmsOrderTrans;


    select firstonly RefRecId from toteContent where toteContent.ToteId == this.ToteId && toteContent.Qty != 0
        join firstonly routeId from wmsOrderTrans where wmsOrderTrans.RecId == toteContent.RefRecId;

    consolRoute = MobConsolidatedPickingRouteOrders::belongsTo(wmsOrderTrans.routeId);

    return consolRoute ? consolRoute : wmsOrderTrans.routeId;
}

public display NoYes pickingRouteIsConsolidated()
{

    MobToteContent		toteContent;
    WMSOrderTrans		wmsOrderTrans;

    select firstonly RefRecId from toteContent where toteContent.ToteId == this.ToteId && toteContent.Qty != 0
        join firstonly routeId from wmsOrderTrans where wmsOrderTrans.RecId == toteContent.RefRecId;

    return MobConsolidatedPickingRouteOrders::Exists(wmsOrderTrans.routeId);
}
